1	@import "tailwindcss";
2	@import "tw-animate-css";
3	@import "shadcn/tailwind.css";
4	
5	@custom-variant dark (&:is(.dark *));
6	
7	@theme inline {
8	  /* ──────────────────────────────────────────────────────────
9	     INKOS BRAND SWATCHES — Brand Book v1.0 (LOCKED)
10	     Bone · Onyx · Stone · Rust — no additions, no substitutes
11	  ────────────────────────────────────────────────────────── */
12	  --color-bone: #F7F7F5;
13	  --color-onyx: #0F0F0F;
14	  --color-stone: #787774;
15	  --color-rust: #B23A2B;
16	
17	  --font-sans: var(--font-sans), 'Inter', -apple-system, sans-serif;
18	  --font-serif: var(--font-serif), 'Instrument Serif', Georgia, serif;
19	  --font-mono: var(--font-mono), 'JetBrains Mono', monospace;
20	
21	  /* ──────────────────────────────────────────────────────────
22	     SEMANTIC PALETTE — derived from brand swatches
23	     Rule: never pure #FFF or #000. Bone/Onyx only.
24	  ────────────────────────────────────────────────────────── */
25	
26	  /* Bone — 60% usage. Page canvas + sidebar bg. */
27	  --color-background: #F7F7F5;
28	
29	  /* Onyx — 20% usage. Primary text + CTAs. */
30	  --color-foreground: #0F0F0F;
31	
32	  /* Card surface — pure white on Bone, so cards "float" */
33	  --color-card: #FFFFFF;
34	  --color-card-foreground: #0F0F0F;
35	
36	  --color-popover: #FFFFFF;
37	  --color-popover-foreground: #0F0F0F;
38	
39	  /* Primary = Onyx (NOT Rust). Primary CTAs are black. */
40	  --color-primary: #0F0F0F;
41	  --color-primary-foreground: #F7F7F5;
42	
43	  /* Secondary — muted Bone tint */
44	  --color-secondary: oklch(96% 0.003 60);
45	  --color-secondary-foreground: #0F0F0F;
46	
47	  /* Muted — Stone-tinted backgrounds */
48	  --color-muted: oklch(95% 0.003 60);
49	  --color-muted-foreground: #787774;
50	
51	  /* Accent — Rust at 12% opacity for active nav states */
52	  --color-accent: rgba(178, 58, 43, 0.08);
53	  --color-accent-foreground: #B23A2B;
54	
55	  /* Destructive = Rust. Reserved for LIVE pill, active nav, destructive only. */
56	  --color-destructive: #B23A2B;
57	  --color-destructive-foreground: #F7F7F5;
58	
59	  /* ──────────────────────────────────────────────────────────
60	     SEMANTIC STATUS TOKENS
61	  ────────────────────────────────────────────────────────── */
62	  --color-success:            oklch(58% 0.18 145);
63	  --color-success-bg:         oklch(94% 0.05 145);
64	  --color-success-foreground: oklch(26% 0.12 145);
65	  --color-warning:            oklch(70% 0.16 72);
66	  --color-warning-bg:         oklch(94% 0.07 72);
67	  --color-warning-foreground: oklch(36% 0.15 72);
68	
69	  /* Borders — Stone-tinted, warm hue, tuned to be visible on bone canvas */
70	  --color-border: oklch(91% 0.005 85);
71	  --color-input: oklch(91% 0.005 85);
72	  --color-ring: #0F0F0F;
73	
74	  /* ──────────────────────────────────────────────────────────
75	     SHADOWS — custom (never use Tailwind default shadow-sm/md)
76	  ────────────────────────────────────────────────────────── */
77	
78	  /* Soft border shadow for cards on white — bumped alpha so cards read on bone bg */
79	  --shadow-soft: 0 1px 2px 0 oklch(20% 0.02 85 / 0.08), 0 1px 3px 0 oklch(20% 0.02 85 / 0.05);
80	
81	  /* Standard card elevation — visible on off-white page */
82	  --shadow-card: 0 1px 3px 0 oklch(20% 0.02 85 / 0.10), 0 2px 4px -1px oklch(20% 0.02 85 / 0.06);
83	
84	  /* Hover elevation */
85	  --shadow-card-hover: 0 6px 16px -4px oklch(20% 0.02 85 / 0.14), 0 3px 8px -2px oklch(20% 0.02 85 / 0.09);
86	
87	  /* Medium depth for drawers, modals */
88	  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 85 / 0.10), 0 2px 8px -2px oklch(13% 0.015 85 / 0.07);
89	
90	  /* Floating elements — command palette, toasts, tooltips */
91	  --shadow-lift: 0 8px 24px -4px oklch(13% 0.015 85 / 0.14),
92	                 0 4px 10px -2px oklch(13% 0.015 85 / 0.08);
93	
94	  /* Full-screen overlays — modal backdrop shadow on dialog */
95	  --shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 85 / 0.22),
96	                    0 8px 24px -4px oklch(13% 0.015 85 / 0.12);
97	
98	  /* ──────────────────────────────────────────────────────────
99	     RADIUS
100	  ────────────────────────────────────────────────────────── */
101	  --radius: 0.5rem;
102	  --radius-sm: 0.25rem;
103	  --radius-md: 0.5rem;
104	  --radius-lg: 0.75rem;
105	  --radius-xl: 1rem;
106	  --radius-2xl: 1.5rem;   /* 24px — large modals, full-bleed cards */
107	  --radius-full: 9999px;  /* pill buttons, avatar chips, progress bars */
108	
109	  /* ──────────────────────────────────────────────────────────
110	     TYPOGRAPHY
111	  ────────────────────────────────────────────────────────── */
112	  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
113	  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;
114	
115	  /* ──────────────────────────────────────────────────────────
116	     TYPOGRAPHY SCALE — semantic names
117	  ────────────────────────────────────────────────────────── */
118	  --text-display-size:    2.25rem;  /* 36px */
119	  --text-display-height:  2.5rem;   /* 40px */
120	  --text-display-weight:  700;

