210	// ─── References ───────────────────────────────────────────────────────────────
211	
212	export async function addReferenceAction(
213	  projectId: string,
214	  formData: FormData
215	): Promise<ActionResult<{ id: string }>> {
216	  const auth = await getAuthenticatedUser()
217	  if (!auth) return { ok: false, error: 'Not authenticated' }
218	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
219	
220	  const supabase = await createClient()
221	
222	  const file = formData.get('file') as File | null
223	  if (!file) return { ok: false, error: 'No file provided' }
224	
225	  // Upload to Supabase Storage
226	  const fileExt = file.name.split('.').pop() ?? 'jpg'
227	  const storagePath = `${auth.studioId}/${projectId}/refs/${Date.now()}.${fileExt}`
228	
229	  const { error: uploadError } = await supabase.storage
230	    .from('project-references')
231	    .upload(storagePath, file, { upsert: false })
232	
233	  if (uploadError) {
234	    logger.error({ uploadError, projectId }, 'addReferenceAction upload failed')
235	    return { ok: false, error: 'Failed to upload image' }
236	  }
237	
238	  const raw = {
239	    storagePath,
240	    caption: (formData.get('caption') as string) || undefined,
241	    displayOrder: formData.get('displayOrder')
242	      ? Number(formData.get('displayOrder'))
243	      : undefined,
244	  }
245	
246	  const parsed = addReferenceSchema.safeParse(raw)
247	  if (!parsed.success) {
248	    return { ok: false, error: 'Validation failed' }
249	  }
250	
251	  try {
252	    const ref = await addProjectReference(auth.studioId, projectId, parsed.data)
253	    revalidatePath(`/projects/${projectId}`)
254	    return { ok: true, data: { id: ref.id } }
255	  } catch (err) {
256	    logger.error({ err, projectId }, 'addReferenceAction failed')
257	    return { ok: false, error: 'Failed to save reference' }
258	  }
259	}
