366	// ─── Deposit ───────────────────────────────────────────────────────────────────
367	
368	export async function recordDepositAction(
369	  projectId: string,
370	  amountCents: number
371	): Promise<ActionResult<void>> {
372	  const auth = await getAuthenticatedUser()
373	  if (!auth) return { ok: false, error: 'Not authenticated' }
374	  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can record deposits' }
375	
376	  if (amountCents <= 0) return { ok: false, error: 'Amount must be positive' }
377	
378	  try {
379	    await recordDepositToProject(auth.studioId, projectId, amountCents)
380	    revalidatePath(`/projects/${projectId}`)
381	    return { ok: true, data: undefined }
382	  } catch (err) {
383	    logger.error({ err, projectId }, 'recordDepositAction failed')
384	    return { ok: false, error: 'Failed to record deposit' }
385	  }
386	}
387	
388	export async function allocateDepositAction(
389	  projectId: string,
390	  bookingId: string,
391	  amountCents: number
392	): Promise<ActionResult<void>> {
393	  const auth = await getAuthenticatedUser()
394	  if (!auth) return { ok: false, error: 'Not authenticated' }
395	  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can allocate deposits' }
396	
397	  const parsed = allocateDepositSchema.safeParse({ bookingId, amountCents })
398	  if (!parsed.success) {
399	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
400	  }
401	
402	  try {
403	    await allocateDepositToSession(auth.studioId, projectId, bookingId, amountCents)
404	    revalidatePath(`/projects/${projectId}`)
405	    return { ok: true, data: undefined }
406	  } catch (err) {
407	    logger.error({ err, projectId, bookingId }, 'allocateDepositAction failed')
408	    const message = err instanceof Error ? err.message : 'Failed to allocate deposit'
409	    return { ok: false, error: message }
410	  }
411	}
