let query = supabase
  .from('projects')
  .select(`
    id, studio_id, client_id, primary_artist_id, name, description,
    placement, style, status, total_sessions_planned, total_price_cents,
    deposit_pool_cents, deposit_applied_cents, moodboard_url, cover_photo_url,
    started_at, completed_at, created_at, updated_at, stalled_at,
    client:clients!projects_client_id_fkey(id, first_name, last_name),
    primary_artist:artists!projects_primary_artist_id_fkey(id, display_name, avatar_url, sort_order)
  `)
  .eq('studio_id', studioId)

// Sort
const sort = filters.sort ?? 'updated_at'
if (sort === 'updated_at' || sort === 'created_at') {
  query = query.order(sort, { ascending: false })
} else {
  // For client_name, deposit_balance, session_count — sort updated_at as fallback
  // (client-side sort applied after fetch)
  query = query.order('updated_at', { ascending: false })
}

if (filters.statuses && filters.statuses.length > 0) {
  query = query.in('status', filters.statuses)
} else if (filters.status) {
  query = query.eq('status', filters.status)
}
if (filters.artistId) {

let rows = (data ?? []).map((p) => ({
  ...p,
  client: Array.isArray(p.client) ? (p.client[0] ?? null) : (p.client ?? null),
  primary_artist: Array.isArray(p.primary_artist) ? (p.primary_artist[0] ?? null) : (p.primary_artist ?? null),
  sessions_completed: sessionCounts[p.id] ?? 0,
  deposit_balance: Math.max(0, p.deposit_pool_cents - p.deposit_applied_cents),
  stalled_at: (p as Record<string, unknown>)['stalled_at'] as string | null ?? null,
}))

// Client-side sorts for non-DB fields
if (filters.sort === 'client_name') {
  rows = rows.sort((a, b) => {
    const nameA = a.client ? `${a.client.first_name} ${a.client.last_name ?? ''}`.trim() : ''
    const nameB = b.client ? `${b.client.first_name} ${b.client.last_name ?? ''}`.trim() : ''
    return nameA.localeCompare(nameB)
  })
} else if (filters.sort === 'deposit_balance') {
  rows = rows.sort((a, b) => b.deposit_balance - a.deposit_balance)
} else if (filters.sort === 'session_count') {
  rows = rows.sort((a, b) => b.sessions_completed - a.sessions_completed)
}

return rows

