/**
 * Compute quick stats for the projects stats bar.
 * Active = any status NOT in (completed, cancelled, on_hold).
 */
export async function getProjectsStats(studioId: string): Promise<ProjectsStats> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('projects')
    .select('status, deposit_pool_cents, deposit_applied_cents, sessions_completed, total_sessions_planned')
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ error, studioId }, 'getProjectsStats failed')
    return { activeCount: 0, depositPoolCents: 0, avgCompletionPct: 0 }
  }

  const rows = data ?? []
  const inactiveStatuses: ProjectStatus[] = ['completed', 'cancelled', 'on_hold']
  const activeRows = rows.filter((r) => !inactiveStatuses.includes(r.status as ProjectStatus))

  const depositPoolCents = activeRows.reduce(
    (sum, r) => sum + Math.max(0, r.deposit_pool_cents - r.deposit_applied_cents),
    0
  )

  const completionPcts = activeRows
    .filter((r) => r.total_sessions_planned && r.total_sessions_planned > 0)
    .map((r) => ((r.sessions_completed ?? 0) / (r.total_sessions_planned ?? 1)) * 100)

  const avgCompletionPct =
    completionPcts.length > 0
      ? Math.round(completionPcts.reduce((s, v) => s + v, 0) / completionPcts.length)
      : 0

  return {
    activeCount: activeRows.length,
    depositPoolCents,
    avgCompletionPct,
  }
}

