export async function updateProjectStatusAction(
  id: string,
  status: string
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }

  const supabase = await createClient()

  // Fetch old status for activity log
  const { data: existing } = await supabase
    .from('projects')
    .select('status')
    .eq('id', id)
    .eq('studio_id', auth.studioId)
    .single()

  const { error } = await supabase
    .from('projects')
    .update({ status, updated_at: new Date().toISOString() })
    .eq('id', id)
    .eq('studio_id', auth.studioId)

  if (error) {
    logger.error({ error, id, status }, 'updateProjectStatusAction failed')
    return { ok: false, error: 'Failed to update status' }
  }

  // Write activity log — best-effort (non-fatal)
  await supabase
    .from('project_activity_log' as 'projects') // table exists post-migration
    .insert({
      studio_id: auth.studioId,
      project_id: id,
      event_type: 'status_changed',
      old_value: existing?.status ?? null,
      new_value: status,
    } as Parameters<ReturnType<typeof supabase.from>['insert']>[0])
    .then(() => undefined)
    .catch(() => undefined)

  revalidatePath('/projects')
  revalidatePath(`/projects/${id}`)
  return { ok: true, data: undefined }
}

