'use client'

import { useCallback } from 'react'
import { X } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { ProjectStatus } from '@/lib/projects/queries'

interface Artist {
  id: string
  display_name: string
}

interface ProjectFiltersProps {
  activeStatuses: ProjectStatus[]
  activeArtistId: string | null
  artists: Artist[]
  onStatusToggle: (status: ProjectStatus) => void
  onArtistToggle: (artistId: string) => void
  onClear: () => void
}

const STATUS_LABELS: Record<ProjectStatus, string> = {
  planning: 'Planning',
  deposit_paid: 'Deposit Paid',
  active: 'Active',
  healing: 'Healing',
  completed: 'Completed',
  on_hold: 'On Hold',
  cancelled: 'Archived',
}

const BOARD_STATUSES: ProjectStatus[] = [
  'planning',
  'deposit_paid',
  'active',
  'healing',
  'completed',
]

const ALL_STATUSES: ProjectStatus[] = [
  'planning',
  'deposit_paid',
  'active',
  'healing',
  'completed',
  'on_hold',
  'cancelled',
]

function FilterChip({
  label,
  active,
  onToggle,
  onRemove,
}: {
  label: string
  active: boolean
  onToggle: () => void
  onRemove?: () => void
}) {
  if (active) {
    return (
      <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-medium bg-foreground text-background">
        {label}
        {onRemove && (
          <button
            onClick={(e) => {
              e.stopPropagation()
              onRemove()
            }}
            className="rounded-full hover:opacity-70 transition-opacity"
            aria-label={`Remove ${label} filter`}
          >
            <X className="h-2.5 w-2.5" />
          </button>
        )}
      </span>
    )
  }

  return (
    <button
      onClick={onToggle}
      className={cn(
        'px-2.5 py-1 rounded-full text-[11px] font-medium border border-border',
        'text-muted-foreground hover:text-foreground hover:border-foreground/30 transition-colors'
      )}
    >
      {label}
    </button>
  )
}

export function ProjectFilters({
  activeStatuses,
  activeArtistId,
  artists,
  onStatusToggle,
  onArtistToggle,
  onClear,
}: ProjectFiltersProps) {
  const hasActiveFilters = activeStatuses.length > 0 || activeArtistId !== null

  const handleStatusToggle = useCallback(
    (s: ProjectStatus) => {
      onStatusToggle(s)
    },
    [onStatusToggle]
  )

  return (
    <div className="flex flex-wrap items-center gap-1.5">
      {/* Status chips */}
      {ALL_STATUSES.map((s) => (
        <FilterChip
          key={s}
          label={STATUS_LABELS[s]}
          active={activeStatuses.includes(s)}
          onToggle={() => handleStatusToggle(s)}
          onRemove={activeStatuses.includes(s) ? () => handleStatusToggle(s) : undefined}
        />
      ))}

      {/* Artist chips */}
      {artists.map((a) => (
        <FilterChip
          key={a.id}
          label={a.display_name}
          active={activeArtistId === a.id}
          onToggle={() => onArtistToggle(a.id)}
          onRemove={activeArtistId === a.id ? () => onArtistToggle(a.id) : undefined}
        />
      ))}

      {/* Clear all */}
      {hasActiveFilters && (
        <button
          onClick={onClear}
          className="px-2.5 py-1 text-[11px] text-muted-foreground hover:text-foreground transition-colors"
        >
          Clear all
        </button>
      )}
    </div>
  )
}

