// ─── Constants ────────────────────────────────────────────────────────────────

type BoardStatus = 'planning' | 'deposit_paid' | 'active' | 'healing' | 'completed'

const BOARD_COLUMNS: { id: BoardStatus; label: string }[] = [
  { id: 'planning', label: 'Planning' },
  { id: 'deposit_paid', label: 'Deposit Paid' },
  { id: 'active', label: 'Active' },
  { id: 'healing', label: 'Healing' },
  { id: 'completed', label: 'Complete' },
]

const STALLED_THRESHOLD_MS = 45 * 24 * 60 * 60 * 1000 // 45 days

// ─── Transition confirm dialog ────────────────────────────────────────────────

interface TransitionDialogProps {
  open: boolean
  fromStatus: BoardStatus
  toStatus: BoardStatus
  projectName: string
  onConfirm: () => void
  onCancel: () => void
  isPending: boolean
}

function transitionMessage(from: BoardStatus, to: BoardStatus): string {
  if (from === 'planning' && to === 'deposit_paid') {
    return 'Mark deposit received from client? This will move the project to "Deposit Paid".'
  }
  if (to === 'healing') {
    return 'Mark the final tattoo session complete? The project will enter the healing phase.'
  }
  if (to === 'completed') {
    return 'Mark this project as fully complete? This closes the deposit pool and archives the timeline.'
  }
  return `Move this project from ${from.replace('_', ' ')} to ${to.replace('_', ' ')}?`
}

function TransitionDialog({
  open,
  fromStatus,
  toStatus,
  projectName,
  onConfirm,
  onCancel,
  isPending,
}: TransitionDialogProps) {
  return (
    <Dialog open={open} onOpenChange={(v) => !v && onCancel()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="text-base font-semibold">Confirm status change</DialogTitle>
        </DialogHeader>
        <p className="text-sm text-muted-foreground">
          <span className="font-medium text-foreground">{projectName}</span>{' — '}
          {transitionMessage(fromStatus, toStatus)}
        </p>
        <DialogFooter className="gap-2">
          <Button variant="outline" size="sm" onClick={onCancel} disabled={isPending}>
            Cancel
          </Button>
          <Button size="sm" onClick={onConfirm} loading={isPending}>
            Confirm
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ─── Board card ───────────────────────────────────────────────────────────────

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase() ?? '')
    .join('')
}

function DepositPill({ project }: { project: ProjectListItem }) {
  const { deposit_pool_cents, deposit_balance } = project

  if (deposit_pool_cents <= 0) return null

  if (deposit_balance === 0) {
    return (
      <span className="px-2 py-0.5 rounded-full text-[10px] font-medium bg-success-bg text-success-foreground">
        {formatCurrency(deposit_pool_cents)} in pool
      </span>
    )
  }

  if (project.status === 'planning') {
    return (
      <span className="px-2 py-0.5 rounded-full text-[10px] font-medium bg-warning-bg text-warning-foreground">
        Pending
      </span>
    )
  }

  return (
    <span className="px-2 py-0.5 rounded-full text-[10px] font-medium bg-muted text-muted-foreground">
      Pool applied
    </span>
  )
}

function StalledPill({ project }: { project: ProjectListItem }) {
  if (project.status !== 'planning') return null

  const ref = project.stalled_at ?? project.updated_at
  const ms = Date.now() - new Date(ref).getTime()
  if (ms < STALLED_THRESHOLD_MS) return null

  const days = Math.floor(ms / (24 * 60 * 60 * 1000))

  return (
    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-medium text-muted-foreground border border-border">
      <span className="h-1.5 w-1.5 rounded-full bg-destructive inline-block" />
      Stalled {days}d
    </span>
  )
}

interface BoardCardInnerProps {
  project: ProjectListItem
  isDragging?: boolean
}

function BoardCardInner({ project, isDragging }: BoardCardInnerProps) {
  const router = useRouter()
  const clientName = project.client
    ? `${project.client.first_name}${project.client.last_name ? ` ${project.client.last_name}` : ''}`
    : 'Unknown client'

  const artistName = project.primary_artist?.display_name ?? null
  const styles = project.style ? project.style.split(',').map((s) => s.trim()).slice(0, 2) : []

  const sessionProgress =
    project.total_sessions_planned && project.total_sessions_planned > 0
      ? project.sessions_completed / project.total_sessions_planned
      : null

  return (
    <div
      className={cn(
        'rounded-lg border border-border bg-card p-3 space-y-2.5 cursor-grab active:cursor-grabbing',
        'shadow-[var(--shadow-card)]',
        isDragging && 'opacity-50'
      )}
      onClick={() => router.push(`/projects/${project.id}`)}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') router.push(`/projects/${project.id}`)
      }}
      aria-label={`${project.name} — click to open`}
    >
      {/* Moodboard thumb grid */}
      <div className="grid grid-cols-2 gap-0.5 rounded-md overflow-hidden aspect-video bg-muted">
        {project.cover_photo_url ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={project.cover_photo_url}
            alt={project.name}
            className="col-span-2 row-span-2 h-full w-full object-cover"
          />
        ) : (
          <>
            <div className="bg-stone/10 flex items-center justify-center">
              <FolderKanban className="h-4 w-4 text-muted-foreground/40" />
            </div>
            <div className="bg-stone/15" />
            <div className="bg-stone/8" />
            <div className="bg-stone/12" />
          </>
        )}
      </div>

      {/* Project name */}
      <p className="text-[13px] font-semibold text-foreground line-clamp-1 leading-snug">
        {project.name}
      </p>

      {/* Client + artist */}
      <div className="space-y-1">
        <div className="flex items-center gap-1.5">
          <div
            className="h-4 w-4 rounded-full bg-muted flex items-center justify-center shrink-0 text-[8px] font-bold text-muted-foreground"
            aria-hidden="true"
          >
            {getInitials(clientName)}
          </div>
          <span className="text-[11px] text-muted-foreground truncate">{clientName}</span>
        </div>
        {artistName && (
          <div className="flex items-center gap-1.5">
            <div
              className="h-4 w-4 rounded-full bg-accent flex items-center justify-center shrink-0 text-[8px] font-bold text-accent-foreground"
              aria-hidden="true"
            >
              {getInitials(artistName)}
            </div>
            <span className="text-[11px] text-muted-foreground truncate">{artistName}</span>
          </div>
        )}
      </div>

      {/* Style tags */}
      {styles.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {styles.map((s) => (
            <span
              key={s}
              className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-secondary text-secondary-foreground"
            >
              {s}
            </span>
          ))}
        </div>
      )}

      {/* Session progress bar */}
      {sessionProgress !== null && (
        <div className="space-y-1">
          <div className="h-1 rounded-full bg-muted overflow-hidden">
            <div
              className="h-full bg-foreground/60 rounded-full transition-all duration-300"
              style={{ width: `${Math.round(sessionProgress * 100)}%` }}
            />
          </div>
          <p className="text-[10px] text-muted-foreground tabular-nums">
            {project.sessions_completed} / {project.total_sessions_planned} sessions
          </p>
        </div>
      )}

      {/* Pills row */}
      <div className="flex flex-wrap gap-1">
        <DepositPill project={project} />
        <StalledPill project={project} />
      </div>
    </div>
  )
}

// ─── Draggable card wrapper ───────────────────────────────────────────────────

function DraggableCard({ project }: { project: ProjectListItem }) {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: project.id,
    data: { project },
  })

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      style={{ touchAction: 'none' }}
