  const { setNodeRef, isOver } = useDroppable({ id: status })

  const displayed = isCompleted && !showAll ? projects.slice(0, 2) : projects
  const hiddenCount = isCompleted ? projects.length - 2 : 0

  return (
    <div className="flex flex-col min-w-0 w-[260px] shrink-0">
      {/* Column header */}
      <div className="flex items-center justify-between mb-2 px-0.5">
        <div className="flex items-center gap-2">
          <span className="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
            {label}
          </span>
          <span className="text-[11px] font-medium tabular-nums text-muted-foreground/60">
            {projects.length}
          </span>
        </div>
        {canCreate && (
          <button
            onClick={() =>
              router.push(`/projects/new?status=${status}`)
            }
            className="h-5 w-5 rounded flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label={`New ${label} project`}
          >
            <Plus className="h-3.5 w-3.5" />
          </button>
        )}
      </div>

      {/* Drop zone */}
      <div
        ref={setNodeRef}
        className={cn(
          'flex-1 space-y-2 min-h-[120px] rounded-lg p-1.5 transition-colors duration-150',
          isOver && 'bg-accent ring-1 ring-accent-foreground/20'
        )}
      >
        {displayed.map((p) => (
          <DraggableCard key={p.id} project={p} />
        ))}

        {isCompleted && projects.length > 2 && !showAll && hiddenCount > 0 && (
          <button
            onClick={() => setShowAll(true)}
            className="w-full text-center text-[11px] text-muted-foreground hover:text-foreground transition-colors py-2"
          >
            + {hiddenCount} more complete
