        {projects.length === 0 && (
          <div className="flex items-center justify-center h-16 rounded-md border border-dashed border-border">
            <span className="text-[11px] text-muted-foreground/50">Drop here</span>
          </div>
        )}
      </div>
    </div>
  )
}

// ─── Main board ───────────────────────────────────────────────────────────────

interface ProjectsBoardViewProps {
  projects: ProjectListItem[]
  canCreate: boolean
}

interface PendingTransition {
  projectId: string
  projectName: string
  fromStatus: BoardStatus
  toStatus: BoardStatus
}

export function ProjectsBoardView({ projects, canCreate }: ProjectsBoardViewProps) {
  const [localProjects, setLocalProjects] = useState<ProjectListItem[]>(projects)
  const [activeId, setActiveId] = useState<string | null>(null)
  const [pendingTransition, setPendingTransition] = useState<PendingTransition | null>(null)
  const [isPending, startTransition] = useTransition()

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } })
  )

  const activeProject = activeId ? localProjects.find((p) => p.id === activeId) ?? null : null

  const getColumn = useCallback(
    (status: BoardStatus) => localProjects.filter((p) => p.status === status),
    [localProjects]
  )

  const handleDragStart = useCallback((event: DragStartEvent) => {
    setActiveId(event.active.id as string)
  }, [])

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      setActiveId(null)
      const { active, over } = event
      if (!over) return

      const projectId = active.id as string
      const toStatus = over.id as BoardStatus
      const project = localProjects.find((p) => p.id === projectId)
      if (!project) return
      if (project.status === toStatus) return

      const fromStatus = project.status as BoardStatus
      if (!BOARD_COLUMNS.some((c) => c.id === toStatus)) return

      setPendingTransition({
        projectId,
        projectName: project.name,
        fromStatus,
        toStatus,
      })
    },
    [localProjects]
  )

  const confirmTransition = useCallback(() => {
    if (!pendingTransition) return
    const { projectId, toStatus } = pendingTransition

    // Optimistic update
    setLocalProjects((prev) =>
      prev.map((p) => (p.id === projectId ? { ...p, status: toStatus } : p))
    )
    setPendingTransition(null)

    startTransition(async () => {
      const result = await updateProjectStatusAction(projectId, toStatus)
      if (!result.ok) {
        // Revert
        setLocalProjects(projects)
        toast.error(result.error)
        logger.error({ projectId, toStatus }, 'status transition failed')
      } else {
        toast.success('Status updated')
      }
    })
  }, [pendingTransition, projects])

  const cancelTransition = useCallback(() => {
    setPendingTransition(null)
  }, [])

  return (
    <>
      <div className="flex gap-4 overflow-x-auto pb-4" role="region" aria-label="Project board">
        {BOARD_COLUMNS.map((col) => (
          <BoardColumn
            key={col.id}
            status={col.id}
            label={col.label}
            projects={getColumn(col.id)}
            canCreate={canCreate}
            isCompleted={col.id === 'completed'}
          />
        ))}
      </div>

      <DndContext
        sensors={sensors}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <DragOverlay>
          {activeProject ? (
            <div className="rotate-1 opacity-90 w-[260px]">
              <BoardCardInner project={activeProject} />
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>

      {pendingTransition && (
        <TransitionDialog
          open
          fromStatus={pendingTransition.fromStatus}
          toStatus={pendingTransition.toStatus}
          projectName={pendingTransition.projectName}
          onConfirm={confirmTransition}
          onCancel={cancelTransition}
          isPending={isPending}
        />
      )}
    </>
  )
}

