'use client'

import Link from 'next/link'
import { FolderKanban } from 'lucide-react'
import { cn, formatCurrency } from '@/lib/utils'
import type { ProjectListItem } from '@/lib/projects/queries'

interface ProjectsGalleryViewProps {
  projects: ProjectListItem[]
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase() ?? '')
    .join('')
}

const STATUS_LABELS: Record<string, string> = {
  planning: 'Planning',
  deposit_paid: 'Deposit Paid',
  active: 'Active',
  healing: 'Healing',
  completed: 'Completed',
  on_hold: 'On Hold',
  cancelled: 'Archived',
}

export function ProjectsGalleryView({ projects }: ProjectsGalleryViewProps) {
  return (
    <div className="columns-2 sm:columns-3 lg:columns-4 xl:columns-5 gap-3 space-y-3">
      {projects.map((project) => (
        <GalleryTile key={project.id} project={project} />
      ))}
    </div>
  )
}

function GalleryTile({ project }: { project: ProjectListItem }) {
  const clientName = project.client
    ? `${project.client.first_name}${project.client.last_name ? ` ${project.client.last_name}` : ''}`
    : 'Unknown client'

  const artistName = project.primary_artist?.display_name ?? null
  const hasDeposit = project.deposit_pool_cents > 0

  return (
    <Link
      href={`/projects/${project.id}`}
      className={cn(
        'group block break-inside-avoid rounded-xl overflow-hidden border border-border',
        'shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-card-hover)]',
        'transition-all duration-200 ease-out hover:-translate-y-0.5',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring'
      )}
    >
      {/* Full-bleed cover — Pinterest style, no fixed aspect */}
      <div className="relative bg-muted min-h-[140px]">
        {project.cover_photo_url ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={project.cover_photo_url}
            alt={project.name}
            className="w-full h-auto object-cover transition-transform duration-300 group-hover:scale-[1.02]"
          />
        ) : (
          <div className="flex items-center justify-center h-[140px]">
            <FolderKanban className="h-10 w-10 text-muted-foreground/30" />
          </div>
        )}

        {/* Status overlay */}
        <span className="absolute top-2 left-2 px-2 py-0.5 rounded-full text-[10px] font-medium bg-foreground/80 text-background backdrop-blur-sm">
          {STATUS_LABELS[project.status] ?? project.status}
        </span>
      </div>

      {/* Minimal info strip */}
      <div className="p-2.5 space-y-1.5">
        <p className="text-[12px] font-semibold text-foreground line-clamp-1 leading-snug">
          {project.name}
        </p>

        <div className="flex items-center gap-1.5">
          <div
            className="h-4 w-4 rounded-full bg-muted flex items-center justify-center shrink-0 text-[8px] font-bold text-muted-foreground"
            aria-hidden="true"
          >
            {getInitials(clientName)}
          </div>
          <span className="text-[11px] text-muted-foreground truncate">{clientName}</span>
        </div>

        {artistName && (
          <div className="flex items-center gap-1.5">
            <div
              className="h-4 w-4 rounded-full bg-accent flex items-center justify-center shrink-0 text-[8px] font-bold text-accent-foreground"
              aria-hidden="true"
            >
              {getInitials(artistName)}
            </div>
            <span className="text-[11px] text-muted-foreground truncate">{artistName}</span>
          </div>
        )}

        {hasDeposit && project.deposit_balance > 0 && (
          <p className="text-[10px] text-muted-foreground tabular-nums">
            {formatCurrency(project.deposit_balance)} balance
          </p>
        )}
      </div>
    </Link>
  )
}

