type ViewMode = 'board' | 'list' | 'gallery' | 'timeline'

const STATUS_CONFIG: Record<string, string> = {
  planning: 'bg-secondary text-secondary-foreground',
  deposit_paid: 'bg-success-bg text-success-foreground',
  active: 'bg-success-bg text-success-foreground',
  healing: 'bg-warning-bg text-warning-foreground',
  completed: 'bg-muted text-muted-foreground',
  on_hold: 'bg-warning-bg text-warning-foreground',
  cancelled: 'bg-muted text-muted-foreground',
}

const SORT_OPTIONS: { value: string; label: string }[] = [
  { value: 'updated_at', label: 'Last activity' },
  { value: 'created_at', label: 'Created date' },
  { value: 'client_name', label: 'Client name' },
  { value: 'deposit_balance', label: 'Deposit balance' },
  { value: 'session_count', label: 'Session count' },
]

// ─── View toggle button ───────────────────────────────────────────────────────

function ViewToggle({
  view,
  onChange,
}: {
  view: ViewMode
