    { key: 'V then L', desc: 'List view' },
    { key: 'V then G', desc: 'Gallery view' },
    { key: 'V then T', desc: 'Timeline view' },
    { key: 'F', desc: 'Toggle filters' },
    { key: 'Esc', desc: 'Close / clear selection' },
