          {shortcuts.map((s) => (
            <div key={s.key} className="flex items-center justify-between">
              <span className="text-xs text-muted-foreground">{s.desc}</span>
              <kbd className="text-[10px] font-mono bg-muted px-1.5 py-0.5 rounded border border-border text-foreground">
                {s.key}
              </kbd>
