// ─── Table view ───────────────────────────────────────────────────────────────

function ProjectsTable({ projects }: { projects: ProjectListItem[] }) {
  const router = useRouter()

  return (
    <div className="rounded-lg border border-border overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Project</TableHead>
            <TableHead>Client</TableHead>
            <TableHead className="hidden sm:table-cell">Artist</TableHead>
            <TableHead className="hidden md:table-cell">Sessions</TableHead>
            <TableHead className="hidden lg:table-cell">Deposit</TableHead>
            <TableHead>Status</TableHead>
            <TableHead className="hidden xl:table-cell text-right">Updated</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {projects.map((project) => {
            const clientName = project.client
              ? `${project.client.first_name}${project.client.last_name ? ` ${project.client.last_name}` : ''}`
              : '—'

            const sessionLabel = project.total_sessions_planned
              ? `${project.sessions_completed} / ${project.total_sessions_planned}`
              : `${project.sessions_completed}`

            const statusClass = STATUS_CONFIG[project.status] ?? STATUS_CONFIG.active
            const statusLabel = STATUS_LABELS[project.status as ProjectStatus] ?? project.status

            return (
              <TableRow
                key={project.id}
                className="cursor-pointer hover:bg-muted/50 transition-colors"
                onClick={() => router.push(`/projects/${project.id}`)}
              >
                <TableCell>
                  <div className="font-medium text-sm text-foreground line-clamp-1">
                    {project.name}
                  </div>
                  {project.placement && (
                    <div className="text-xs text-muted-foreground line-clamp-1">
                      {project.placement}
                    </div>
                  )}
                </TableCell>
                <TableCell className="text-sm text-muted-foreground">{clientName}</TableCell>
                <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                  {project.primary_artist?.display_name ?? '—'}
                </TableCell>
                <TableCell className="hidden md:table-cell text-sm tabular-nums">
                  {sessionLabel}
                </TableCell>
                <TableCell className="hidden lg:table-cell text-sm tabular-nums">
                  {project.deposit_pool_cents > 0
                    ? formatCurrency(project.deposit_pool_cents)
                    : '—'}
                </TableCell>
                <TableCell>
                  <span
                    className={cn(
                      'px-2 py-0.5 rounded-full text-[11px] font-medium',
                      statusClass
                    )}
                  >
                    {statusLabel}
                  </span>
                </TableCell>
                <TableCell className="hidden xl:table-cell text-xs text-muted-foreground text-right">
                  {formatDate(project.updated_at)}
                </TableCell>
              </TableRow>
            )
          })}
        </TableBody>
      </Table>
    </div>
  )
}

// ─── Main component ───────────────────────────────────────────────────────────

const VIEW_STORAGE_KEY = 'inkos:projects-view'
const DEMO_STORAGE_KEY = 'inkos:project-demo'

function persistView(v: ViewMode) {
  if (typeof localStorage !== 'undefined') {
    localStorage.setItem(VIEW_STORAGE_KEY, v)
  }
}

function readPersistedView(): ViewMode {
  if (typeof localStorage === 'undefined') return 'board'
  const v = localStorage.getItem(VIEW_STORAGE_KEY)
  if (v === 'board' || v === 'list' || v === 'gallery' || v === 'timeline') return v
  return 'board'
}

export function ProjectsListClient({
  initialProjects,
  artists,
  role,
  initialFilters,
  stats,
}: ProjectsListClientProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const [isPending, startTransition] = useTransition()
  const [viewMode, setViewMode] = useState<ViewMode>(() => readPersistedView())
  const [showFilters, setShowFilters] = useState(false)
  const [showShortcuts, setShowShortcuts] = useState(false)
  const [isDemoMode, setIsDemoMode] = useState(false)

  // Local search state (debounced → URL)
  const [searchValue, setSearchValue] = useState(initialFilters.search ?? '')
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const searchRef = useRef<HTMLInputElement>(null)

  // Keyboard: awaiting second key after 'V'
  const vPressedRef = useRef(false)
  const vTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  // Check demo mode from localStorage on mount
  useEffect(() => {
    if (typeof localStorage !== 'undefined') {
      setIsDemoMode(localStorage.getItem(DEMO_STORAGE_KEY) === '1')
    }
  }, [])

  const updateParam = useCallback(
    (key: string, value: string | null) => {
      const current = new URLSearchParams(Array.from(searchParams.entries()))
      if (value && value !== 'all') {
        current.set(key, value)
      } else {
        current.delete(key)
      }
      const qs = current.toString()
      startTransition(() => {
        router.push(`${pathname}${qs ? `?${qs}` : ''}`)
      })
    },
    [router, pathname, searchParams]
  )

  const handleSearchChange = useCallback(
    (value: string) => {
      setSearchValue(value)
      if (debounceRef.current) clearTimeout(debounceRef.current)
      debounceRef.current = setTimeout(() => {
        updateParam('search', value || null)
      }, 300)
    },
    [updateParam]
  )

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current)
    }
  }, [])

  const handleViewChange = useCallback((v: ViewMode) => {
    setViewMode(v)
    persistView(v)
  }, [])

  // Parse multi-status from URL
  const activeStatuses: ProjectStatus[] = (() => {
    const raw = searchParams.get('status')
    if (!raw) return []
    return raw
      .split(',')
      .filter((s): s is ProjectStatus => ALL_STATUSES.includes(s as ProjectStatus))
  })()

  const activeArtistId = searchParams.get('artistId')
  const activeSort = searchParams.get('sort') ?? 'updated_at'

  const handleStatusToggle = useCallback(
    (status: ProjectStatus) => {
      const next = activeStatuses.includes(status)
        ? activeStatuses.filter((s) => s !== status)
        : [...activeStatuses, status]
      updateParam('status', next.length > 0 ? next.join(',') : null)
    },
    [activeStatuses, updateParam]
  )

  const handleArtistToggle = useCallback(
    (artistId: string) => {
      updateParam('artistId', activeArtistId === artistId ? null : artistId)
    },
    [activeArtistId, updateParam]
  )

  const handleClearFilters = useCallback(() => {
    const current = new URLSearchParams(Array.from(searchParams.entries()))
    current.delete('status')
    current.delete('artistId')
    const qs = current.toString()
    startTransition(() => {
      router.push(`${pathname}${qs ? `?${qs}` : ''}`)
    })
  }, [router, pathname, searchParams])

  const handleEnableDemo = useCallback(() => {
    localStorage.setItem(DEMO_STORAGE_KEY, '1')
    setIsDemoMode(true)
  }, [])

  const handleDismissDemo = useCallback(() => {
    localStorage.removeItem(DEMO_STORAGE_KEY)
    setIsDemoMode(false)
  }, [])

  // Keyboard shortcuts
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      // Skip if focused on an input/textarea
      const target = e.target as HTMLElement
      if (
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.isContentEditable
      ) {
        // Allow Esc to blur
        if (e.key === 'Escape') {
          ;(target as HTMLInputElement).blur?.()
        }
        return
      }

      if (e.key === 'Escape') {
        setShowShortcuts(false)
        return
      }

      if (e.key === '?') {
        e.preventDefault()
        setShowShortcuts((prev) => !prev)
        return
      }

      if (e.key === '/') {
        e.preventDefault()
        searchRef.current?.focus()
        return
      }

      if (e.key === 'F' || e.key === 'f') {
        e.preventDefault()
        setShowFilters((prev) => !prev)
        return
      }

      if (e.key === 'P' || e.key === 'p') {
        e.preventDefault()
        router.push('/projects/new')
        return
      }

      // V then B/L/G/T
      if (e.key === 'V' || e.key === 'v') {
        e.preventDefault()
        vPressedRef.current = true
        if (vTimeoutRef.current) clearTimeout(vTimeoutRef.current)
        vTimeoutRef.current = setTimeout(() => {
          vPressedRef.current = false
        }, 1500)
        return
      }

      if (vPressedRef.current) {
        const keyMap: Record<string, ViewMode> = {
          b: 'board',
          B: 'board',
          l: 'list',
          L: 'list',
          g: 'gallery',
          G: 'gallery',
          t: 'timeline',
          T: 'timeline',
        }
        if (keyMap[e.key]) {
          e.preventDefault()
          handleViewChange(keyMap[e.key])
          vPressedRef.current = false
        }
      }
    }

    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [router, handleViewChange])

  const canCreate = role !== 'guest_artist'

  // Show demo projects if in demo mode and no real projects
  const displayProjects =
    isDemoMode && initialProjects.length === 0
      ? // lazy import to avoid bundle cost when not needed
        []
      : initialProjects

  const showEmpty = !isDemoMode && initialProjects.length === 0 && !isPending

  return (
    <>
      {/* Stats bar */}
      <ProjectsStatsBar stats={isDemoMode ? { activeCount: 3, depositPoolCents: 140000, avgCompletionPct: 38 } : stats} />

      {/* Demo banner */}
      {isDemoMode && <DemoBanner onDismiss={handleDismissDemo} />}

      {/* Controls row */}
      <div className="flex flex-wrap items-center gap-2">
        {/* Search */}
        <div className="relative flex-1 min-w-[200px] max-w-xs">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" aria-hidden="true" />
          <Input
            ref={searchRef}
            placeholder="Search projects…"
            value={searchValue}
            onChange={(e) => handleSearchChange(e.target.value)}
            className="pl-8 h-9 text-sm"
            aria-label="Search projects"
          />
          {searchValue && (
            <button
              onClick={() => handleSearchChange('')}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              aria-label="Clear search"
            >
              <X className="h-3 w-3" aria-hidden="true" />
            </button>
          )}
        </div>

        {/* Filter toggle */}
        <Button
          variant="outline"
          size="sm"
          className="h-9 gap-1.5"
          onClick={() => setShowFilters((p) => !p)}
          aria-expanded={showFilters}
          aria-label="Toggle filters"
        >
          <SlidersHorizontal className="h-3.5 w-3.5" aria-hidden="true" />
          Filter
          {activeStatuses.length > 0 && (
            <span className="h-4 w-4 rounded-full bg-foreground text-background text-[10px] font-medium flex items-center justify-center tabular-nums">
              {activeStatuses.length}
            </span>
          )}
        </Button>

        {/* Sort */}
        <Select value={activeSort} onValueChange={(v) => updateParam('sort', v)}>
          <SelectTrigger className="h-9 w-40 text-sm" aria-label="Sort projects">
            <SelectValue placeholder="Sort" />
          </SelectTrigger>
          <SelectContent>
            {SORT_OPTIONS.map((o) => (
              <SelectItem key={o.value} value={o.value}>
                {o.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {/* View toggle */}
        <div className="ml-auto">
          <ViewToggle view={viewMode} onChange={handleViewChange} />
        </div>
      </div>

      {/* Filter chips */}
      {showFilters && (
        <ProjectFilters
          activeStatuses={activeStatuses}
          activeArtistId={activeArtistId}
          artists={artists}
          onStatusToggle={handleStatusToggle}
          onArtistToggle={handleArtistToggle}
          onClear={handleClearFilters}
        />
      )}

      {/* Content */}
      <div className="flex-1 py-2">
        {isPending ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {Array.from({ length: 6 }).map((_, i) => (
              <Skeleton key={i} className="h-64 rounded-xl" />
            ))}
          </div>
        ) : showEmpty ? (
          <EmptyProjects
            canCreate={canCreate}
            onNew={() => router.push('/projects/new')}
            onDemo={handleEnableDemo}
          />
        ) : viewMode === 'board' ? (
          <BoardWithDemo isDemoMode={isDemoMode} projects={displayProjects} canCreate={canCreate} />
        ) : viewMode === 'gallery' ? (
          <GalleryWithDemo isDemoMode={isDemoMode} projects={displayProjects} />
        ) : viewMode === 'timeline' ? (
          <TimelinePlaceholder />
        ) : (
          <ListWithDemo isDemoMode={isDemoMode} projects={displayProjects} />
        )}
      </div>

      {/* Shortcuts overlay */}
      {showShortcuts && <ShortcutOverlay onClose={() => setShowShortcuts(false)} />}
    </>
  )
}

// ─── Demo-aware view wrappers ─────────────────────────────────────────────────

function BoardWithDemo({
  isDemoMode,
  projects,
  canCreate,
}: {
  isDemoMode: boolean
  projects: ProjectListItem[]
  canCreate: boolean
}) {
  const [demoProjects, setDemoProjects] = useState<ProjectListItem[] | null>(null)

