      import('@/lib/projects/demo-data').then((m) => setDemoProjects(m.DEMO_PROJECTS))
    }
  }, [isDemoMode, projects.length])

  const displayed = isDemoMode && projects.length === 0 ? (demoProjects ?? []) : projects
  return <ProjectsBoardView projects={displayed} canCreate={canCreate} />
}

