"use client"

/**
 * Context menu — right-click triggered menu.
 * Built on Base UI Menu primitive (same as DropdownMenu) with a custom
 * anchor that intercepts the contextmenu event.
 */

import * as React from "react"
import { Menu as MenuPrimitive } from "@base-ui/react/menu"
import { cn } from "@/lib/utils"

// ─── Root ──────────────────────────────────────────────────────────────────────

function ContextMenu({ children, ...props }: MenuPrimitive.Root.Props) {
  return (
    <MenuPrimitive.Root data-slot="context-menu" {...props}>
      {children}
    </MenuPrimitive.Root>
  )
}

// ─── Trigger ───────────────────────────────────────────────────────────────────

/**
 * Wraps its children so that right-clicking opens the context menu.
 * `asChild` is accepted but the actual triggering is done by the wrapper div.
 */
function ContextMenuTrigger({
  children,
  asChild: _asChild,
  className,
  ...props
}: React.ComponentProps<"div"> & { asChild?: boolean }) {
  // We use the MenuPrimitive.Trigger as the anchor and intercept the
  // contextmenu event on the wrapping div to programmatically open.
  const triggerRef = React.useRef<HTMLButtonElement>(null)

  const handleContextMenu = React.useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      e.preventDefault()
      triggerRef.current?.click()
    },
    []
  )

  return (
    <div
      className={cn("relative", className)}
      onContextMenu={handleContextMenu}
      data-slot="context-menu-trigger"
      {...props}
    >
      {children}
      {/* Hidden trigger button that Base UI uses as the anchor */}
      <MenuPrimitive.Trigger
        ref={triggerRef}
        aria-label="Open context menu"
        className="sr-only"
        style={{ position: 'absolute', top: 0, left: 0 }}
      />
    </div>
  )
}

// ─── Content ───────────────────────────────────────────────────────────────────

function ContextMenuContent({
  align = "start",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 4,
  className,
  ...props
}: MenuPrimitive.Popup.Props &
  Pick<
    MenuPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  >) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          data-slot="context-menu-content"
          className={cn(
            "z-50 max-h-(--available-height) min-w-32 origin-(--transform-origin) overflow-x-hidden overflow-y-auto rounded-lg bg-popover p-1 text-popover-foreground shadow-[var(--shadow-soft-md)] ring-1 ring-foreground/10 duration-100 outline-none",
            "data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
            "data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95",
            "data-closed:animate-out data-closed:overflow-hidden data-closed:fade-out-0 data-closed:zoom-out-95",
            className
          )}
          {...props}
        />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  )
}

// ─── Item ──────────────────────────────────────────────────────────────────────

function ContextMenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: MenuPrimitive.Item.Props & {
  inset?: boolean
  variant?: "default" | "destructive"
}) {
  return (
    <MenuPrimitive.Item
      data-slot="context-menu-item"
      data-inset={inset}
      data-variant={variant}
      className={cn(
        "group/context-menu-item relative flex cursor-default items-center gap-1.5 rounded-md px-1.5 py-1 text-sm outline-hidden select-none",
        "focus:bg-accent focus:text-accent-foreground",
        "data-inset:pl-7",
        "data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 data-[variant=destructive]:focus:text-destructive",
        "data-disabled:pointer-events-none data-disabled:opacity-50",
        "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    />
  )
}

// ─── Separator ─────────────────────────────────────────────────────────────────

function ContextMenuSeparator({
  className,
  ...props
}: MenuPrimitive.Separator.Props) {
  return (
    <MenuPrimitive.Separator
      data-slot="context-menu-separator"
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  )
}

// ─── Label ─────────────────────────────────────────────────────────────────────

function ContextMenuLabel({
  className,
  inset,
  ...props
}: MenuPrimitive.GroupLabel.Props & { inset?: boolean }) {
  return (
    <MenuPrimitive.Group>
      <MenuPrimitive.GroupLabel
        data-slot="context-menu-label"
        data-inset={inset}
        className={cn(
          "px-1.5 py-1 text-xs font-medium text-muted-foreground data-inset:pl-7",
          className
        )}
        {...props}
      />
    </MenuPrimitive.Group>
  )
}

export {
  ContextMenu,
  ContextMenuTrigger,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuLabel,
}

